import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/alert.css";

export type AlertVariant = "default" | "success" | "warning" | "danger";

export interface AlertProps extends ComponentPropsWithoutRef<"div"> {
  variant?: AlertVariant;
  /** Optional icon shown at the start. Decorative, so give it aria-hidden. */
  icon?: ReactNode;
}

/**
 * Inline message that stays on the page (unlike a Toast, which disappears).
 * Use `role="alert"` only for errors the user must notice right away.
 */
export function Alert({ variant = "default", icon, className, children, ...props }: AlertProps) {
  return (
    <div className={cn("eui-alert", `eui-alert--${variant}`, className)} {...props}>
      {icon ? <span className="eui-alert__icon">{icon}</span> : null}
      <div className="eui-alert__body">{children}</div>
    </div>
  );
}

export function AlertTitle({ className, ...props }: ComponentPropsWithoutRef<"p">) {
  return <p className={cn("eui-alert__title", className)} {...props} />;
}

export function AlertDescription({ className, ...props }: ComponentPropsWithoutRef<"div">) {
  return <div className={cn("eui-alert__description", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Alert. A tinted surface with a hairline ring. Status is shown by an accent bar and
   the icon, never by color alone, so the message still reads in grayscale. */

.eui-alert {
  --eui-alert-accent: var(--eui-color-fg-muted);

  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--eui-radius-base);
  background-color: var(--eui-color-surface);
  color: var(--eui-color-fg);
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
  font-size: 14px;
  line-height: 20px;
}

.eui-alert--success { --eui-alert-accent: var(--eui-color-accent); }
.eui-alert--warning { --eui-alert-accent: #b45309; }
.eui-alert--danger { --eui-alert-accent: var(--eui-color-danger); }

.eui-alert__icon {
  flex: none;
  display: inline-flex;
  margin-top: 1px;
  color: var(--eui-alert-accent);
}

.eui-alert__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.eui-alert__title {
  margin: 0;
  font-weight: 600;
}

.eui-alert__description {
  color: var(--eui-color-fg-muted);
}
